class Solution:
    def queryConversions(self, conversions: List[List[int]], queries: List[List[int]]) -> List[int]:
        MOD = 10**9 + 7
        n = len(conversions) + 1
        adj = [[] for _ in range(n)]
        for u, v, f in conversions:
            adj[u].append((v, f))
            adj[v].append((u, f))
        w = [1] * n
        stack = [(0, -1)]
        while stack:
            u, par = stack.pop()
            for v, f in adj[u]:
                if v != par:
                    w[v] = w[u] * f % MOD
                    stack.append((v, u))
        return [w[a] * pow(w[b], MOD - 2, MOD) % MOD for a, b in queries]

