class Solution {
public:
    vector<int> queryConversions(vector<vector<int>>& conversions, vector<vector<int>>& queries) {
        const long long MOD = 1000000007LL;
        int n = conversions.size() + 1;
        vector<vector<pair<int,int>>> adj(n);
        for (auto& e : conversions) { adj[e[0]].push_back({e[1], e[2]}); adj[e[1]].push_back({e[0], e[2]}); }
        vector<long long> w(n, 1);
        vector<int> stk = {0};
        vector<bool> vis(n, false); vis[0] = true;
        while (!stk.empty()) {
            int u = stk.back(); stk.pop_back();
            for (auto [v, f] : adj[u]) if (!vis[v]) { vis[v] = true; w[v] = w[u] * f % MOD; stk.push_back(v); }
        }
        auto pw = [&](long long b, long long e) { long long r = 1; b %= MOD; while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; } return r; };
        vector<int> ans;
        for (auto& q : queries) ans.push_back(w[q[0]] * pw(w[q[1]], MOD - 2) % MOD);
        return ans;
    }
};

