class Solution {
    public int[] queryConversions(int[][] conversions, int[][] queries) {
        final long MOD = 1000000007L;
        int n = conversions.length + 1;
        List<List<long[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : conversions) { adj.get(e[0]).add(new long[]{e[1], e[2]}); adj.get(e[1]).add(new long[]{e[0], e[2]}); }
        long[] w = new long[n]; Arrays.fill(w, 1);
        Deque<Integer> stk = new ArrayDeque<>(); stk.push(0);
        boolean[] vis = new boolean[n]; vis[0] = true;
        while (!stk.isEmpty()) {
            int u = stk.pop();
            for (long[] ed : adj.get(u)) { int v = (int) ed[0]; if (!vis[v]) { vis[v] = true; w[v] = w[u] * ed[1] % MOD; stk.push(v); } }
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            long inv = pow(w[queries[i][1]], MOD - 2, MOD);
            ans[i] = (int) (w[queries[i][0]] * inv % MOD);
        }
        return ans;
    }
    private long pow(long b, long e, long m) { long r = 1; b %= m; while (e > 0) { if ((e & 1) == 1) r = r * b % m; b = b * b % m; e >>= 1; } return r; }
}

