var queryConversions = function(conversions, queries) {
    const MOD = 1000000007n, B = BigInt;
    const n = conversions.length + 1;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, f] of conversions) { adj[u].push([v, B(f)]); adj[v].push([u, B(f)]); }
    const w = new Array(n).fill(1n);
    const stk = [0], vis = new Array(n).fill(false); vis[0] = true;
    while (stk.length) {
        const u = stk.pop();
        for (const [v, f] of adj[u]) if (!vis[v]) { vis[v] = true; w[v] = w[u] * f % MOD; stk.push(v); }
    }
    const pw = (b, e) => { let r = 1n; b %= MOD; while (e > 0n) { if (e & 1n) r = r * b % MOD; b = b * b % MOD; e >>= 1n; } return r; };
    return queries.map(([a, b]) => Number(w[a] * pw(w[b], MOD - 2n) % MOD));
};
